function frame(ms){let dt=Math.min(.035,(ms-last)/1000||.016);last=ms;
if(!S.paused){
 if(layerTween<1)layerTween=Math.min(1,layerTween+dt*1.6);
 if(mixProgress<1)mixProgress=Math.min(1,mixProgress+dt*.8);
 if(S.mode==='layers'&&S.layers.released)layerObjectProgress=Math.min(1,layerObjectProgress+dt*.8);
 if(S.mode==='compare'&&S.compare.tested&&S.compare.kind==='solids'){let c=S.compare;for(let n=0;n<4;n++){for(let i=0;i<2;i++){let m=MATERIALS.find(m=>m.id===(i?c.b:c.a)),v=i?c.volume:volA();solidStep(i?bodyB:bodyA,dt/4,{mass:m.rho*v,volume:v,rho:fluid(i?c.fb:c.fa,c.salt).rho});}}}
 if(S.mode==='drop'&&S.drop.released){let d=S.drop,rho=ethanolDensity(d.percent);for(let n=0;n<5;n++)sphereStep(dropBody,dt/5,{mass:.969*d.volume,volume:d.volume,rho,depth:.14,drag:.02});dropTime+=dt;const observation=document.querySelector('#drop-observation'),radius=Math.cbrt(3*d.volume/(4*Math.PI))/100,motion=dropBody.z<=-.14+radius+.0001?'Resting on the bottom':dropBody.z>-.02&&Math.abs(dropBody.v)<.0008&&rho>.96918?'Floating at the surface':Math.abs(dropBody.v)<.0008?'Almost still':dropBody.v>0?'Rising':'Sinking';if(observation&&observation.textContent!==motion)observation.textContent=motion;const near=Math.abs(rho-.969)<.00018&&dropBody.z<-.025&&dropBody.z>-.115;if(near)dropSuccess+=dt;else dropSuccess=0;if(dropSuccess>=3&&dropSuccess<3+dt*2){feedback('Near neutral buoyancy! Buoyant force and weight nearly balance. Keep this trial and try another drop size.');updateMission();}}
 if(S.mode==='boat'&&S.boat.tested)boatProgress=Math.min(1,boatProgress+dt*.7);
}
if(reduced){if(S.mode==='compare'&&S.compare.tested){let c=S.compare;for(let i=0;i<2;i++){let m=MATERIALS.find(m=>m.id===(i?c.b:c.a)),v=i?c.volume:volA(),s=Math.cbrt(v)/100,r=fluid(i?c.fb:c.fa,c.salt).rho,fr=floatResult(m.rho*v,v,r),b=i?bodyB:bodyA;b.z=fr.state==='sink'?-.14+s/2:s/2-fr.fraction*s;b.v=0;}}}
draw(S.paused?0:ms/1800);requestAnimationFrame(frame);}
function compareFeedback(){const c=S.compare,solids=c.kind==='solids',a=solids?MATERIALS.find(m=>m.id===c.a):fluid(c.fa,c.salt),b=solids?MATERIALS.find(m=>m.id===c.b):fluid(c.fb,c.salt);let more=Math.abs(a.rho-b.rho)<.00001?'They have the same model density.':`${a.rho>b.rho?'A':'B'} is denser.`;if(solids&&c.tested){let ra=floatResult(a.rho*volA(),volA(),fluid(c.fa,c.salt).rho),rb=floatResult(b.rho*c.volume,c.volume,fluid(c.fb,c.salt).rho);return `A ${ra.state==='float'?'floats':ra.state==='sink'?'sinks':'is neutrally buoyant'}; B ${rb.state==='float'?'floats':rb.state==='sink'?'sinks':'is neutrally buoyant'}. Use the mass and volume measurements to explain the result.`;}
return 'Measurements recorded. Use mass and volume together to decide which sample is denser, then explain your evidence.';}
const predictionNames={a:'A is denser',b:'B is denser',same:'Same density',lower:'Settle lower',upper:'Stay higher',blend:'Blend with another liquid',unsure:'I need more evidence',rise:'Rise',stay:'Stay suspended',sink:'Sink',float:'Floats',flood:'Floods and sinks'};
let compared=new Set(),mixVisual=null,mixProgress=1;
function liquidName(p){return fluid(p.id).name+(p.id==='salt'&&p.salt!=null?' ('+num(p.salt)+' g salt / 100 g)':'');}
function layerResult(){return layerTest(S.layers.entries,MATERIALS.find(m=>m.id===S.layers.sample).rho);}
function layerObservation(){const eq=layerResult();if(!eq)return '';
return eq.state==='bottom'?(eq.shallow?'The sample rests on the bottom. This shallow layer cannot support it fully; try more liquid.':'The sample reaches the bottom. Compare its density with the liquids.') :eq.state==='surface'?'The sample floats at the upper surface. What evidence explains this?':'The sample settles between layers. Buoyant forces balance its weight.';}
function pourSignature(pours){const sums={};for(const p of pours){const key=p.id+':'+(p.rho??p.mass/p.volume).toFixed(6);sums[key]=(sums[key]||0)+p.volume;}return JSON.stringify(Object.entries(sums).sort());}
function pourAmounts(pours){const grouped=new Map();for(const p of pours){const key=p.id+':'+(p.rho??p.mass/p.volume).toFixed(6),old=grouped.get(key);if(old)old.volume+=p.volume;else grouped.set(key,{...p});}return [...grouped.entries()].sort(([a],[b])=>a.localeCompare(b)).map(([,p])=>liquidName(p)+' ('+num(p.volume)+' mL)').join('; ');}
function pourSequence(pours){return pours.map(p=>p.id+':'+(p.rho??p.mass/p.volume).toFixed(6)).filter((p,i,a)=>i===0||p!==a[i-1]).join(' → ');}
function recordExperiment(mode,predictionText=null){
 const c=S.compare,l=S.layers,d=S.drop,b=S.boat;let title,conditions={},observations={},meta={mode},data={};
 if(predictionText==null)predictionText=predictionNames[S[mode].prediction]||'Not recorded before this test';
 if(mode==='compare'){const solids=c.kind==='solids',a=solids?MATERIALS.find(m=>m.id===c.a):fluid(c.fa,c.salt),bb=solids?MATERIALS.find(m=>m.id===c.b):fluid(c.fb,c.salt);title=solids?'Compare solids':'Compare liquids';conditions={'Sample A':a.name,'A volume':num(volA())+(solids?' cm³':' mL'),'Sample B':bb.name,'B volume':num(c.volume)+(solids?' cm³':' mL')};if(solids){conditions['Fluid A']=liquidName({...fluid(c.fa),salt:c.salt});conditions['Fluid B']=liquidName({...fluid(c.fb),salt:c.salt});}observations=c.measured?{'A mass':num(a.rho*volA())+' g','B mass':num(bb.rho*c.volume)+' g'}:{'Mass measurements':'Not measured in this test'};if(solids)observations.Observation=c.tested?compareFeedback():'Mass measured; floating test not run.';}
 if(mode==='layers'){title='Layer liquids';const layers=layerOrder(l.entries);conditions={'Liquids and amounts':pourAmounts(l.pours),'Pour order':l.poursKnown?l.pours.map(p=>liquidName(p)).join(' → '):'Not recorded in this older experiment','Observation stage':({early:'Before standing',standing:'After standing',stirred:'After stirring'}[l.phase])};if(l.released)conditions['Test object']=MATERIALS.find(m=>m.id===l.sample).name;observations={'Order, bottom to top':layers.map(e=>e.name+' ('+num(e.volume)+' mL)').join(' → '),'Total volume':num(layers.reduce((a,e)=>a+e.volume,0))+' mL'};if(l.released)observations.Observation=layerObservation();if(l.pours.length)observations['Last liquid poured']=liquidName(l.pours.at(-1));meta={...meta,pourSignature:pourSignature(l.pours),pourSequence:pourSequence(l.pours),poursKnown:l.poursKnown,phase:l.phase,layerCount:layers.length};}
 if(mode==='drop'){title='Suspend an oil drop';conditions={'Alcohol in 100 g mixture':num(d.percent)+' g','Water in 100 g mixture':num(100-d.percent)+' g','Castor-oil drop':d.volume+' mL'};observations.Observation=Math.abs(ethanolDensity(d.percent)-.969)<.00018?'Near neutral buoyancy':ethanolDensity(d.percent)>.969?'Tends to rise':'Tends to sink';meta={...meta,percent:d.percent,volume:d.volume,near:Math.abs(ethanolDensity(d.percent)-.969)<.00018};}
 if(mode==='boat'){title='Build a floater';const m=boatModel(b.width,b.height,b.cargo);conditions={'Hull width':num(b.width)+' cm','Hull side height':num(b.height)+' cm','Hull length':'12 cm','Clay':'100 g · 50 cm³','Cargo':b.cargo+' g','Fluid':'Fresh water'};observations={'Hull size (outside)':num(b.width*12*b.height)+' cm³','Hull above water':m.flooded?'0 cm':num(m.freeboard,2)+' cm','Observation':m.flooded?'Flooded and sank':'Floating with a dry interior'};meta={...meta,cargo:b.cargo,hullSize:b.width*12*b.height,floats:!m.flooded};}
 data={...conditions,...observations};S[mode].attempt=structuredClone({title,prediction:predictionText,data,conditions,observations,meta});persist();
}
function keepTrial(){const attempt=S[S.mode].attempt;if(!attempt){feedback('Run a test first, then keep its evidence.');return;}if(S.trials.length>=100){feedback('100 trials are kept. Download your records before clearing space.');return;}
 S.trials.push({...structuredClone(attempt),id:crypto.randomUUID?.()||Date.now()+'-'+Math.random().toString(36).slice(2),reflection:''});persist();updateMission();feedback('Trial kept. Open My trials to explain it or compare two tests.');}
function missionHTML(){const mode=S.mode,s=S[mode],key=s.challenge;if(key==='explore')return '';let goal='',status='';
 if(mode==='compare'){goal=({same:'Keep the volumes equal. Weigh both samples and use the evidence to compare their density.',big:'A has twice the volume of B. Can the larger object still be less dense? Weigh, test, and explain.',fluid:'Keep the two solids identical. Find fluids that make one float and the other sink.'}[key]||'');status=s.tested?'Both samples tested. Use mass and volume to explain your result.':s.measured?'Mass recorded. What do mass and volume tell you?':'';}
 if(mode==='layers'){const ours=S.trials.filter(t=>t.meta?.mode==='layers');if(key==='three'){goal='Build three layers that remain separate after Let it stand.';status=s.phase!=='early'?(layerOrder(s.entries).length===3?'Three layers remain. Keep your evidence.':layerOrder(s.entries).length+' layer(s) remain. What could you change?'):'';}
 if(key==='order'){goal='Use the same liquids and amounts in two different pouring orders. Let each stand, then keep and compare both trials.';status=ours.some((a,i)=>a.meta.poursKnown&&a.meta.phase==='standing'&&ours.slice(i+1).some(b=>b.meta.poursKnown&&b.meta.phase==='standing'&&a.meta.pourSignature===b.meta.pourSignature&&a.meta.pourSequence!==b.meta.pourSequence))?'Two different orders saved. Compare them in My trials.':!s.poursKnown&&s.entries.length?'Use Reset to start a new recorded pouring order.':'';}
 if(key==='mix'){goal='Keep a trial before stirring. Stir, keep another, and compare which boundaries remain.';status=ours.some((a,i)=>ours.slice(i+1).some(b=>a.meta.pourSignature===b.meta.pourSignature&&a.meta.phase!=='stirred'&&b.meta.phase==='stirred'))?'Before and after saved. Compare them in My trials.':s.phase==='stirred'?'Look closely: which boundaries disappeared?':'';}}
 if(mode==='drop'){goal=({suspend:'Find a mixture that holds the drop almost still in the middle. Adjust the alcohol in small steps.',direction:'Keep a rising-drop trial and a sinking-drop trial. Which change reversed its direction?',size:'Suspend one drop size and keep it. Test a different size in the same mixture, then compare.'}[key]||'');const ours=S.trials.filter(t=>t.meta?.mode==='drop');status=key==='direction'&&ours.some(t=>t.observations?.Observation==='Tends to rise')&&ours.some(t=>t.observations?.Observation==='Tends to sink')?'Both directions saved. Compare the mixtures.':key==='size'&&ours.some((a,i)=>a.meta.near&&ours.slice(i+1).some(b=>b.meta.near&&Math.abs(a.meta.percent-b.meta.percent)<.11&&a.meta.volume!==b.meta.volume))?'Two drop sizes suspended in the same mixture. Explain your evidence.':dropSuccess>=3?'Near balance. Keep this trial and explain why.':'';}
 if(mode==='boat'){goal='Carry '+key+' g with the smallest hull you can make. Cargo stays fixed; change the hull, test, and compare designs.';if(s.tested){const m=boatModel(s.width,s.height,s.cargo),size=s.width*12*s.height;status=m.flooded?'Water crossed the rim. What could you change?':Math.abs(size-hullBenchmark(+key))<.01?'Smallest floating hull available in this model. Keep and explain your design.':'It floats: '+num(size)+' cm³ outside. Can a smaller hull carry the same cargo?';}}
 return goal?`<div class="mission"><span>${goal}</span>${status?`<strong>${status}</strong>`:''}</div>`:'';
}
function updateMission(){const el=$('#mission');if(el)el.innerHTML=missionHTML();}
function describeScene(){if(S.mode==='layers'){const l=S.layers;return 'Bottom to top: '+(layerOrder(l.entries).map(e=>e.name+', '+num(e.volume)+' mL').join('; ')||'empty beaker')+'. '+(l.released?layerObservation():'');}if(S.mode==='compare')return S.compare.tested?compareFeedback():'Two samples ready. Choose Weigh both to record mass.';if(S.mode==='drop')return S.drop.released?'Castor-oil drop in '+num(S.drop.percent)+' g alcohol per 100 g mixture.':'Oil drop ready to release at the centre.';const m=boatModel(S.boat.width,S.boat.height,S.boat.cargo);return S.boat.tested?(m.flooded?'Hull flooded.':'Hull floating with '+num(m.freeboard,2)+' cm above water.'):'Hull ready to test.';}
function observationView(){if(matchMedia('(max-width:800px), (max-height:600px)').matches)canvas.parentElement.scrollIntoView({block:'center',behavior:reduced?'instant':'smooth'});}
function changed(path,value){const [group,key]=path.split('.');S[group][key]=value;const s=S[group];
 if(group==='compare'&&key!=='forces'){s.measured=false;s.tested=false;s.attempt=null;s.prediction='';resetBodies();notice='';if(key==='challenge'){if(value==='big'){s.kind='solids';s.a='cork';s.b='concrete';}if(value==='fluid'){s.kind='solids';s.a=s.b='plastic';s.fa='ethanol';s.fb='water';}}if(s.challenge==='fluid'&&['a','b'].includes(key))s.a=s.b=value;}
 if(group==='layers'){if(key==='selected'){s.prediction='';}if(key==='sample')s.released=false;}
 if(group==='drop'){if(key==='percent'){s.percent=clamp(+value,0,60);s.prediction='';dropSuccess=0;notice='';if(s.released)recordExperiment('drop','Not recorded before adjusting to this mixture');else s.attempt=null;$('#alcohol-output').textContent=`${num(s.percent)} g alcohol · ${num(100-s.percent)} g water`;$('#mixture-density').textContent=num(ethanolDensity(s.percent),4);$('#alcohol').value=s.percent;$('#feedback').textContent='';document.querySelectorAll('[data-predict^="drop:"]').forEach(e=>{e.disabled=!!s.attempt;e.setAttribute('aria-pressed','false');});const legend=$('.prediction legend');if(legend)legend.textContent=s.attempt?'No prediction recorded':'Your prediction';updateMission();persist();return;}
 if(key==='volume'){s.released=false;s.attempt=null;s.prediction='';dropBody={z:-.07,v:0};dropSuccess=0;}}
 if(group==='boat'){s.tested=false;s.attempt=null;s.prediction='';boatProgress=0;notice='';if(key==='challenge'&&value!=='explore')s.cargo=Number(value);}
 render();persist();}
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;
 if(el.dataset.mode){S.mode=el.dataset.mode;notice='';resetBodies();render();history.replaceState(null,'','#'+S.mode);return;}
 if(el.dataset.dialog){openDialog(el.dataset.dialog);return;}
 if(el.dataset.predict){const [mode,value]=el.dataset.predict.split(':');if(predictionLocked(mode))return;S[mode].prediction=value;document.querySelectorAll(`[data-predict^="${mode}:"]`).forEach(b=>b.setAttribute('aria-pressed',b===el));persist();return;}
 if(el.dataset.kind){const c=S.compare;c.kind=el.dataset.kind;if(c.kind==='liquids'&&!['explore','same'].includes(c.challenge))c.challenge='explore';c.prediction='';c.attempt=null;c.measured=false;c.tested=false;notice='';resetBodies();render();return;}
 if(el.dataset.fluid){changed('layers.selected',el.dataset.fluid);return;}
 if(el.dataset.nudge){changed('drop.percent',Math.round(clamp(S.drop.percent+Number(el.dataset.nudge),0,60)*10)/10);return;}
 const act=el.dataset.action;
 if(act==='weigh'){const p=S.compare.attempt?.prediction;S.compare.measured=true;recordExperiment('compare',p);notice=compareFeedback();render();announce(notice);}
 if(act==='compare-test'){if(S.compare.tested)resetBodies();const p=S.compare.attempt?.prediction;S.compare.tested=true;recordExperiment('compare',p);notice=compareFeedback();render();announce(notice);observationView();}
 if(act==='compare-reset'){Object.assign(S.compare,{tested:false,measured:false,attempt:null,prediction:''});notice='';resetBodies();render();}
 if(act==='pour'){const l=S.layers;if(l.entries.reduce((a,x)=>a+x.volume,0)+l.portion>600)return;const added=entry(l.selected,l.portion,l.salt);currentPour={before:structuredClone(layerOrder(l.entries)),added};mixVisual=null;mixProgress=1;l.entries=addPour(l.entries,added);if(l.entries.some(e=>e.id==='mix'&&!currentPour.before.some(b=>b.id==='mix'&&Math.abs(b.volume-e.volume)<1e-8))){mixVisual={before:currentPour.before};mixProgress=reduced?1:0;currentPour=null;}l.pours.push({...added.ingredients[0]});layerTween=reduced?1:0;l.phase='early';l.released=false;const pred=predictionNames[l.prediction];recordExperiment('layers',pred?`Before pouring ${l.portion} mL of ${liquidName(added.ingredients[0])}: ${pred}`:'Not recorded before this pour');l.prediction='';notice=`Poured ${l.portion} mL of ${liquidName(added.ingredients[0])}. Observe where it settles.`;render();announce(notice);observationView();}
 if(act==='wait'||act==='stir'){const l=S.layers;currentPour=null;layerTween=1;mixVisual={before:structuredClone(layerOrder(l.entries))};mixProgress=reduced?1:0;l.entries=coalesceLayers(blendLayers(l.entries,act==='stir'));l.phase=act==='stir'?'stirred':'standing';l.released=false;recordExperiment('layers','Not recorded before '+(act==='stir'?'stirring':'letting the liquids stand'));notice=act==='stir'?'Watch the boundaries fade as compatible liquids blend. Oil stays separate.':'Adjacent compatible liquids blend. An oil layer can keep water and alcohol apart.';render();announce(notice);observationView();}
 if(act==='layer-object'){S.layers.released=true;layerObjectProgress=reduced?1:0;recordExperiment('layers','Not recorded before dropping this object');notice=layerObservation();render();announce(notice);observationView();}
 if(act==='layer-reset'){currentPour=null;mixVisual=null;layerTween=mixProgress=1;Object.assign(S.layers,{entries:[],pours:[],poursKnown:true,phase:'early',released:false,attempt:null,prediction:''});notice='';render();}
 if(act==='release'){S.drop.released=true;dropBody={z:-.07,v:0};dropSuccess=dropTime=0;recordExperiment('drop',S.drop.attempt?.prediction);notice='Drop released. Watch, then adjust the mixture in small steps.';render();announce(notice);observationView();}
 if(act==='drop-reset'){S.drop.released=false;S.drop.attempt=null;S.drop.prediction='';dropBody={z:-.07,v:0};dropSuccess=0;notice='Drop reset. You can make a new prediction before releasing it.';render();}
 if(act==='boat-test'){S.boat.tested=true;boatProgress=0;recordExperiment('boat',S.boat.attempt?.prediction);const b=S.boat,m=boatModel(b.width,b.height,b.cargo);notice=m.flooded?'Water crosses the rim and fills the hull. Change its shape and try again.':b.challenge==='explore'?'The hull floats with a dry interior. Keep this design, then change one thing.':'It floats. Compare its size with another design carrying the same cargo.';render();announce(notice);observationView();}
 if(act==='boat-reset'){S.boat.tested=false;S.boat.attempt=null;S.boat.prediction='';notice='';render();}
 if(act==='cargo-plus'){changed('boat.cargo',Math.min(650,S.boat.cargo+25));}
 if(act==='save')keepTrial();if(act==='csv')exportCSV();if(act==='print-trials')printPage(false);if(act==='print-worksheet')printPage(true);
 if(act==='compare-trials')openDialog('comparison');if(act==='back-trials')openDialog('trials');
 if(act==='clear-trials'&&confirm('Clear your kept trials and explanations on this browser?')){S.trials=[];compared.clear();persist();openDialog('trials');}
 if(el.id==='motion'){S.paused=!S.paused;el.textContent=S.paused?'Resume motion':'Pause motion';persist();}
 if(el.id==='close-dialog')$('#dialog').close();
});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.state){const key=el.dataset.state.split('.')[1],val=el.type==='checkbox'?el.checked:el.type==='range'||['volume','portion'].includes(key)?Number(el.value):el.value;changed(el.dataset.state,val);}
 if(el.dataset.compareTrial){const id=el.dataset.compareTrial,t=S.trials.find(t=>t.id===id);if(el.checked){const first=S.trials.find(t=>compared.has(t.id));if(compared.size>=3||(first&&first.title!==t.title)){el.checked=false;$('#comparison-note').textContent=compared.size>=3?'Compare up to three trials at a time.':'Choose trials from the same investigation.';return;}compared.add(id);}else compared.delete(id);const b=$('[data-action="compare-trials"]');b.textContent='Compare selected · '+compared.size;b.disabled=compared.size<2;$('#comparison-note').textContent=compared.size>=2?'Ready to compare what changed and what happened.':'Select two or three trials from the same investigation.';}
});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.state&&el.type==='range'){if(el.dataset.state==='drop.percent'){changed(el.dataset.state,Number(el.value));return;}const label=el.closest('.range-control')?.querySelector('output');if(label){const suffix=label.textContent.replace(/[0-9.,\s]/g,'');label.textContent=el.value+' '+suffix;}}
 if(el.dataset.reflection){const trial=S.trials.find(t=>t.id===el.dataset.reflection);if(trial){trial.reflection=el.value.slice(0,6000);persist();}}});
function download(name,content,mime){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type:mime}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCSV(){const quote=s=>'"'+String(s??'').replace(/"/g,'""')+'"';let rows=[['Investigation','Prediction','Measurements and observations','Explanation'],...S.trials.map(t=>[t.title,t.prediction,Object.entries(t.data).map(([k,v])=>k+': '+v).join('; '),t.reflection])];download('Float-Lab-Trials.csv','\ufeff'+rows.map(r=>r.map(s=>quote(/^[=+@-]/.test(String(s))?'\''+s:s)).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
function trialHTML(t,i){return `<article class="trial"><div class="trial-heading"><h3>${i+1}. ${esc(t.title)}</h3><label class="check"><input type="checkbox" data-compare-trial="${esc(t.id)}" ${compared.has(t.id)?'checked':''}>Compare</label></div><dl><dt>Prediction before testing</dt><dd>${esc(t.prediction)}</dd>${Object.entries(t.data).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl><label>My explanation: what changed, and what evidence supports it?<textarea maxlength="6000" data-reflection="${esc(t.id)}">${esc(t.reflection)}</textarea></label></article>`;}
function comparisonHTML(){const chosen=S.trials.filter(t=>compared.has(t.id));if(chosen.length<2)return '<p>Select two or three trials in My trials.</p>';const modern=chosen.every(t=>t.conditions&&t.observations),groups=modern?[['What was set','conditions'],['What happened','observations']]:[['Recorded evidence','data']];let rows='';for(const [title,part] of groups){rows+=`<tr class="comparison-section"><th colspan="${chosen.length+1}">${title}</th></tr>`;const keys=[...new Set(chosen.flatMap(t=>Object.keys(t[part]||{})))];for(const key of keys){const values=chosen.map(t=>t[part]?.[key]??'—'),different=part==='conditions'&&new Set(values).size>1;rows+=`<tr class="${different?'different':''}"><th scope="row">${esc(key)}${different?'<span class="difference-label">Different setting</span>':''}</th>${values.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`;}}return `<p>Compare what was set and what happened. For a fair test, try changing one factor.</p><div class="comparison-scroll" tabindex="0" aria-label="Trial comparison table; scroll horizontally for all columns"><table class="comparison-table"><caption>${esc(chosen[0].title)}</caption><thead><tr><th scope="col">Evidence</th>${chosen.map(t=>`<th scope="col">Trial ${S.trials.indexOf(t)+1}</th>`).join('')}</tr></thead><tbody><tr><th scope="row">Prediction before testing</th>${chosen.map(t=>`<td>${esc(t.prediction)}</td>`).join('')}</tr>${rows}</tbody></table></div><p class="comparison-prompt"><b>Think about it:</b> What stayed the same? What changed? Which result helps you explain why?</p><button data-action="back-trials">Back to my trials and explanations</button>`;}
function openDialog(type){const dialog=$('#dialog'),body=$('#dialog-body');let html='',title='';
if(type==='outcomes'){title='Connected Alberta Grade 5 outcomes';html=outcomesHTML();}
if(type==='teacher'){title='Teacher notes';html=teacherHTML();}
if(type==='trials'){title='My trials';html=`<p>Kept measurements remain as recorded. Add or revise your explanation below. Work stays in this browser; download or print it to keep a separate copy.</p><div class="trial-actions"><button data-action="csv" ${!S.trials.length?'disabled':''}>Download CSV</button><button data-action="print-trials" ${!S.trials.length?'disabled':''}>Print / save PDF</button><button data-action="compare-trials" ${compared.size<2?'disabled':''}>Compare selected · ${compared.size}</button><button class="ghost" data-action="clear-trials" ${!S.trials.length?'disabled':''}>Clear my trials</button></div><p id="comparison-note" class="science-note">Select two or three trials from the same investigation.</p>${S.trials.length?S.trials.map(trialHTML).join(''):'<div class="empty">No kept trials yet. Run an investigation, then choose Keep trial.</div>'}`;}
if(type==='comparison'){title='Compare my trials';html=comparisonHTML();}
if(type==='print'){title='Print / save PDF';html='<p>Choose a blank investigation sheet or your kept trials. In your browser’s print window, choose Save as PDF for a PDF copy.</p><div class="trial-actions"><button data-action="print-worksheet">Blank investigation sheet</button><button data-action="print-trials" '+(!S.trials.length?'disabled':'')+'>My trials and explanations</button></div><p>Printed student sheets contain prompts and spaces for evidence. They do not include an answer key.</p>';}
$('#dialog-title').textContent=title;body.innerHTML=html;if(!dialog.open)dialog.showModal();}
function outcomesHTML(){return `<p>These connections describe the tasks in Float Lab. Each broad learning outcome has additional expectations beyond this simulation.</p>
<article class="outcome"><span class="basis">MATTER · DIRECT PRACTICE</span><h3>Particle model and physical properties</h3><p>Students investigate the particle model of matter in relation to the physical properties of solids, liquids, and gases.</p><ul><li>Measure the mass of solids and liquids using a balance scale and SI units.</li><li>Measure the volume of liquids using appropriate instruments and SI units.</li><li>Directly compare the density of solid objects that have the same volume.</li><li>Directly compare the density of liquids.</li></ul><p><b>Where:</b> Compare samples and Layer liquids. Mass is read from simulated tared balances. Liquid volumes are selected and displayed; this supports comparing known volumes, while measuring and reading a physical graduated instrument still needs hands-on practice.</p><p class="coverage">Focused coverage: mass, volume, and comparative density. This version does not teach the full particle model, gas density, compressibility, or all physical measurement techniques.</p></article>
<article class="outcome"><span class="basis">ENERGY · DIRECT PRACTICE / VIRTUAL DESIGN</span><h3>Forces in water and air</h3><p>Students investigate and compare how forces affect living things and objects in water and air.</p><ul><li>Relate buoyant force and weight to the tendency to float or sink in water.</li><li>Conduct controlled experiments to determine if various objects and materials float in different fluids.</li><li>Construct a device that can float.</li></ul><p><b>Where:</b> Compare solids, Suspend a drop, and Build a floater.</p><p class="coverage">The design task is virtual. Pair it with a physical build to address actual construction and safe tool use. Flight, living things in air, and other forces are outside this lab’s scope.</p></article>
<article class="outcome"><span class="basis">SCIENTIFIC METHODS · DIRECT PRACTICE</span><h3>Evidence and controlled experiments</h3><p>Students investigate how evidence is gathered and explain the importance of ethics in science.</p><ul><li>Plan and conduct a controlled experiment.</li><li>Identify the variables in a controlled experiment.</li><li>Apply vocabulary for variables correctly in science contexts.</li><li>Evaluate the effect of the manipulated variable on the responding variable in a controlled experiment.</li><li>Defend a conclusion about cause and effect based on evidence produced in a controlled experiment.</li></ul><p><b>Where:</b> Choose what changes, compare kept trials, and write explanations. Teacher prompts ask students to name manipulated, responding, and controlled variables.</p><p class="coverage">Supports discussion of bias, accurate records, ethical reporting, and communicating evidence. Those topics need explicit discussion; a simulation or exported table alone does not establish full coverage.</p></article>
<article class="outcome"><span class="basis">COMPUTER SCIENCE / DESIGN · SUPPORTING CONNECTION</span><h3>Design to meet a need</h3><p>Students apply design processes when creating artifacts that can be used by a human or machine to address a need.</p><ul><li>Design an artifact to meet a need.</li><li>Evaluate an artifact based on various factors.</li><li>Develop multiple iterations of an artifact.</li><li>Discuss examples of designs that have been enhanced or refined to better meet needs.</li><li>Propose enhancements and refinements to an artifact in collaboration with others.</li></ul><p><b>Where:</b> Build a floater. Compare designs carrying the same cargo, then explain a refinement to a partner.</p><p class="coverage">Supports part of the design outcome. The app does not teach block coding, algorithms, or loops.</p></article>
<p class="sources">Source: <a href="https://curriculum.learnalberta.ca/curriculum/en/c/sci5" target="_blank" rel="noopener">Alberta Grade 5 Science curriculum</a>. Learning outcome and listed skills wording checked against the supplied Alberta curriculum workbook, October 2026.</p>`;}
function teacherHTML(){return `<h3>A short investigation sequence</h3><ol><li>Teach or revisit mass, volume, density, and a fair comparison.</li><li>Ask for a prediction with a reason. Keep a measurement trial before changing a setting.</li><li>Change one variable. Have students name the manipulated variable, responding variable, and the factors held constant.</li><li>Keep a second trial. In My trials, select two or three records and choose Compare selected. Name the manipulated, responding, and controlled variables, then explain the evidence.</li><li>Later, use a different sample or challenge without showing the earlier results.</li></ol><h3>Questions worth discussing</h3><ul><li>Would the heavier sample always be denser? What must you know about its volume?</li><li>Can you make the same object sink in one fluid and float in another?</li><li>Which liquid layers remain after stirring? Why is density alone insufficient to explain mixing?</li><li>Does changing the drop’s volume change the mixture needed for neutral buoyancy?</li><li>Which hull change made a difference when clay mass and cargo stayed the same?</li><li>Could your expectations influence which trials you choose to report?</li></ul><h3>Scientific model</h3><p>Density is mass divided by volume. Buoyant force equals the weight of displaced fluid. At rest, a freely floating object’s buoyant force balances its weight. A sinking object may also receive a support force from the bottom. Surface tension rounds an immiscible oil drop; buoyancy determines its rise or fall.</p><p>Water–ethanol density uses a 20°C reference table indexed by <b>mass percentage</b>, with interpolation. Mixture volumes are not assumed additive for this binary pair. The drop is a model castor-oil sample with density 0.969 g/mL. Its drawn size is enlarged for visibility; its mass, volume, and spherical displacement are calculated at the selected physical size. The slider replaces the surrounding uniform mixture between tests; it does not model the turbulence of pouring directly onto a drop.</p><p>Liquid-layer motion and waiting times are illustrative. Water and ethanol blend when a pour contacts an exposed water–ethanol layer. Other compatible adjacent layers blend when allowed to stand; an intervening oil layer acts as a barrier. Stirring combines water-compatible components and the oil separates again. Complex multi-ingredient blend densities use an additive-volume approximation. Honey, syrup, wood, plastic, and oil vary in real life; the values represent selected model samples, not every product.</p><p>The guided hull challenges hold cargo fixed and seek the smallest outside hull volume among the available dimensions. The drawing is a side cutaway; the interior remains dry until water enters over the rim. The clay-hull model keeps clay volume and mass fixed while changing the dimensions of an open rectangular hull. It models displacement and flooding at the rim; it omits tipping, cracks, surface tension effects on tiny objects, and material strength.</p><h3>Physical classroom connection</h3><p>Follow local classroom safety procedures for any physical activity. The alcohol investigation here is virtual. Choose suitable classroom materials and supervision for hands-on demonstrations.</p><h3>Access and student work</h3><p>Controls work by tap, mouse, or keyboard. No dragging is required. Motion can be paused. Predictions and experiment conditions are captured when a test runs. Adjusting an already released drop creates a new observation with no prior prediction for the changed mixture. Earlier records remain intact. Work is stored locally in this browser, with no account, microphone, analytics, or upload of student explanations. Print or download records before clearing browser storage. The offline copy contains the same models and assets.</p><h3>References</h3><ul class="sources"><li><a href="https://www.jlab.org/ir/CRCHandBooks/15_20_84.pdf" target="_blank" rel="noopener">CRC: density of ethanol–water mixtures</a> (International Critical Tables; hosted by Jefferson Lab).</li><li><a href="https://www.sfu.ca/phys/demos/demoindex/fluids/fl2b/density.html" target="_blank" rel="noopener">Simon Fraser University: fluid and salt-solution reference densities</a>.</li><li><a href="https://www.acs.org/middleschoolchemistry/lessonplans/chapter5/lesson7.html" target="_blank" rel="noopener">American Chemical Society: liquids dissolving in water</a>.</li><li><a href="https://sciencemuseum.ugent.be/engl-plat9.html" target="_blank" rel="noopener">Ghent University Science Museum: Plateau’s experiment</a>.</li><li><a href="https://www.learningscientists.org/blog/2019/1/31-1" target="_blank" rel="noopener">The Learning Scientists: implementing learning strategies</a>.</li></ul><p>Original interface, investigation prompts, models, and generated material artwork for Black Gold School Division. No Gizmos artwork, code, questions, or interface elements are used.</p>`;}
function printPage(blank){let old=$('.print-page');old?.remove();let section=document.createElement('section');section.className='print-page';if(blank){section.innerHTML=`<h1>Float Lab · Investigation record</h1><p>Grade 5 Science · Name: _____________________ Date: ______________</p><div class="print-box"><h3>My question and prediction</h3><div class="worksheet-line"></div><div class="worksheet-line"></div></div><div class="print-box"><h3>A fair test</h3><p>Manipulated variable (what I change):</p><div class="worksheet-line"></div><p>Responding variable (what I observe or measure):</p><div class="worksheet-line"></div><p>Controlled variables (what I keep the same):</p><div class="worksheet-line"></div></div><h3>My evidence</h3><table><tr><th>Trial / what changed</th><th>Measurements, with units</th><th>Observation</th></tr>${Array.from({length:4},()=>'<tr><td style="height:45px"></td><td></td><td></td></tr>').join('')}</table><div class="print-box"><h3>My conclusion</h3><p>Use evidence to explain what happened. Was your prediction supported?</p>${'<div class="worksheet-line"></div>'.repeat(4)}</div><p class="muted">Float Lab · Black Gold School Division · Model results are evidence about the simulation. Compare with real investigations where possible.</p>`;}else{section.innerHTML='<h1>Float Lab · My trials</h1><p>Predictions, measurements, observations, and explanations.</p>'+S.trials.map((t,i)=>`<article class="print-box"><h3>${i+1}. ${esc(t.title)}</h3><p><b>Prediction:</b> ${esc(t.prediction)}</p>${Object.entries(t.data).map(([k,v])=>`<p><b>${esc(k)}:</b> ${esc(v)}</p>`).join('')}<p><b>My explanation:</b></p><p class="reflection-text">${esc(t.reflection||'No explanation recorded.')}</p></article>`).join('');}document.body.append(section);window.print();}
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#dialog').close();}});
window.addEventListener('hashchange',()=>{let m=location.hash.slice(1);if(['compare','layers','drop','boat'].includes(m)){S.mode=m;resetBodies();notice='';render();}});
if(['compare','layers','drop','boat'].includes(location.hash.slice(1)))S.mode=location.hash.slice(1);
resetBodies();render();document.fonts.ready.then(resize);requestAnimationFrame(frame);
